def transform(grid):
    out = [row[:] for row in grid]
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != bg}
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
        c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
        # Hollow rectangular frames are converted into filled panels; the 3x3 marker gets a center.
        if all(grid[r][c] == color for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
               if r in (r0, r1) or c in (c0, c1)):
            if r1-r0 == 2 and c1-c0 == 2:
                out[r0+1][c0+1] = 7
            else:
                for r in range(r0+1, r1):
                    for c in range(c0+1, c1):
                        out[r][c] = 2
    return out
